<?php require '../includes/bootstrap.php';$user=admin_required();$title='Tổng quan & báo cáo';
$month=input('month',date('Y-m'));$dt=DateTimeImmutable::createFromFormat('!Y-m',$month);if(!$dt || $dt->format('Y-m')!==$month){$month=date('Y-m');$dt=new DateTimeImmutable(date('Y-m-01'));}
$start=$dt->format('Y-m-d');$end=$dt->modify('+1 month')->format('Y-m-d');
$cash=query("SELECT COALESCE(SUM(CASE WHEN kind='payment' THEN amount ELSE 0 END),0) collected,COALESCE(SUM(CASE WHEN kind='refund' THEN amount ELSE 0 END),0) refunded FROM payments WHERE created_at>=? AND created_at<?",[$start,$end])->fetch();
$stats=query("SELECT COUNT(*) total,COALESCE(SUM(status='pending'),0) pending,COALESCE(SUM(status='checked_in'),0) staying FROM bookings")->fetch();
$stock=(int)query("SELECT COUNT(*) FROM hotel_rooms WHERE active=1 AND housekeeping<>'maintenance'")->fetchColumn();
$occupied=(int)query("SELECT COUNT(DISTINCT a.room_id) FROM room_assignments a JOIN bookings b ON b.id=a.booking_id WHERE b.status='checked_in'")->fetchColumn();
$missing=(int)query("SELECT COUNT(*) FROM bookings b WHERE b.status='checked_in' AND (SELECT COUNT(*) FROM room_assignments a WHERE a.booking_id=b.id)<>b.quantity")->fetchColumn();
$rows=query("SELECT r.name,COUNT(b.id) total,COALESCE(SUM(CASE WHEN b.status<>'cancelled' THEN b.total_price ELSE 0 END),0) booked_value FROM room_types r LEFT JOIN bookings b ON b.room_type_id=r.id AND b.created_at>=? AND b.created_at<? GROUP BY r.id,r.name ORDER BY r.id",[$start,$end])->fetchAll();
$daily=query("SELECT DATE(created_at) day,COALESCE(SUM(CASE WHEN kind='payment' THEN amount ELSE -CAST(amount AS SIGNED) END),0) net FROM payments WHERE created_at>=? AND created_at<? GROUP BY DATE(created_at) ORDER BY day",[$start,$end])->fetchAll();
require '../includes/staff_header.php'; ?><div class="stats"><div><span>Tổng đơn / mọi thời điểm</span><strong><?=$stats['total']?></strong></div><div><span>Đơn chờ xác nhận</span><strong><?=$stats['pending']?></strong></div><div><span>Phòng đang có khách</span><strong><?=$occupied?> / <?=$stock?></strong></div><div><span>Công suất hiện tại</span><strong><?=$stock?number_format($occupied/$stock*100,1,',','.'):0?>%</strong></div></div><p>Công suất hiện tại = số phòng đã phân cho khách đang ở / số phòng đang hoạt động, không bảo trì. Phòng chờ dọn thuộc mẫu số.</p><?php if($missing): ?><div class="notice error">Có <?=$missing?> đơn đang ở từ bản cũ chưa bổ sung phòng, nên công suất hiện tại chưa đầy đủ. <a href="<?=e(url('reception/rooms.php'))?>">Xử lý tại sơ đồ phòng</a>.</div><?php endif; ?>
<form method="get" class="filter"><label>Tháng báo cáo<input name="month" type="month" value="<?=e($month)?>" required></label><button class="button">XEM BÁO CÁO</button></form><div class="stats"><div><span>Tiền đã thu trong tháng</span><strong><?=money($cash['collected'])?></strong></div><div><span>Tiền đã hoàn trong tháng</span><strong><?=money($cash['refunded'])?></strong></div><div><span>Thu ròng trong tháng</span><strong><?=money((int)$cash['collected']-(int)$cash['refunded'])?></strong></div><div><span>Đơn đang lưu trú</span><strong><?=$stats['staying']?></strong></div></div>
<div class="notice">Thu ròng dựa trên các giao dịch nhân viên đã ghi nhận, không phải lợi nhuận hay doanh thu kế toán. Dữ liệu bản cũ chưa có sổ thu tiền nên không tự suy ra đã thanh toán.</div>
<h2>Đơn tạo trong tháng theo loại phòng</h2><div class="table-wrap"><table><thead><tr><th>Loại phòng</th><th>Tổng đơn (gồm đã hủy)</th><th>Giá trị đơn chưa hủy</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['name'])?></td><td><?=$r['total']?></td><td><?=money($r['booked_value'])?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="spaced-heading">Thu ròng theo ngày</h2><div class="table-wrap"><table><thead><tr><th>Ngày ghi nhận</th><th>Thu − hoàn</th></tr></thead><tbody><?php foreach($daily as $d): ?><tr><td><?=e($d['day'])?></td><td><?=money($d['net'])?></td></tr><?php endforeach; if(!$daily): ?><tr><td colspan="2">Chưa có giao dịch trong tháng này.</td></tr><?php endif; ?></tbody></table></div><?php require '../includes/staff_footer.php'; ?>
